// Bundles the markdown files in /knowledge into lib/knowledge.generated.ts
// so they ship with the app on Vercel. Runs automatically before dev and build.
// Edit the .md files, never the generated file.
import { readFileSync, writeFileSync, readdirSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const k = (p) => readFileSync(join(root, "knowledge", p), "utf8");

const countries = {};
for (const f of readdirSync(join(root, "knowledge", "countries"))) {
  if (f.endsWith(".md")) countries[f.replace(".md", "")] = k(join("countries", f));
}

const out = `// AUTO-GENERATED by scripts/bundle-knowledge.mjs - do not edit.
export const instructions = ${JSON.stringify(k("instructions.md"))};
export const samplePlan = ${JSON.stringify(k("sample-plan-olvae-japan.md"))};
export const countries: Record<string, string> = ${JSON.stringify(countries, null, 2)};
`;
mkdirSync(join(root, "lib"), { recursive: true });
writeFileSync(join(root, "lib", "knowledge.generated.ts"), out);
console.log("Bundled knowledge:", Object.keys(countries).join(", "));
